"""Severity-Classified Transmission (SCT): byte layouts of the 14-byte flash and CANCEL messages and the base-side rules (docs/01_protocol/PROTOCOL_SCT.md, generated by ``write_doc``).

Layouts (little-endian, HMAC-SHA256 truncated to 8 bytes, tag over ALL preceding body bytes, same key as the alert and the ACK):
  byte 0      version (high nibble) | message type (low nibble): FLASH = 4, CANCEL = 5
  bytes 1-2   short node id (u16, low 16 bits of node_id; ASSUMPTION: unique within the fleet)
  bytes 3-4   counter, low 16 bits of the 32-bit alert counter of the event
  byte 5      severity class (high nibble, 0 to 3) | event type (low nibble: 0 crash, 1 rollover, 2 other); for CANCEL the low nibble is the reason (0 driver cancel)
  bytes 6-13  tag
The flash and the full alert of one event carry the SAME 32-bit counter.
"""
from __future__ import annotations

import hashlib
import hmac
import struct
from collections import OrderedDict
from dataclasses import dataclass
from pathlib import Path

from crashguard import packet as P
from crashguard.lora import airtime_ms

MSG_FLASH, MSG_CANCEL = 4, 5
FLASH_LEN, FLASH_BODY_LEN = 14, 6
FLASH_EVENT_ID = 0xFFFFFFFF  # acked_event_id marker in the 26-byte ACK of a flash
RECENT_N = 16
WINDOW = 1 << 15  # a 16-bit counter is reconstructed within +-32,768 of the last value the base has seen

ACCEPT_FLASH, ACCEPT_ALERT = "accept_flash", "accept_alert"
REACK, REJECT_TAG, REJECT_COUNTER, REJECT_TYPE, REJECT_LENGTH, REJECT_VERSION, CANCELLED, REJECT_UNKNOWN = "reack", "reject_tag", "reject_counter", "reject_type", "reject_length", "reject_version", "cancelled", "reject_unknown_event"


@dataclass
class Short:
    node_id: int
    counter: int
    severity: int
    event: int = 0
    msg_type: int = MSG_FLASH
    version: int = P.VERSION


def _tag(key: bytes, body: bytes) -> bytes:
    return hmac.new(key, body, hashlib.sha256).digest()[: P.TAG_LEN]


def encode_short(m: Short, key: bytes) -> bytes:
    body = struct.pack("<BHHB", (m.version << 4) | m.msg_type, m.node_id & 0xFFFF, m.counter & 0xFFFF, ((m.severity & 0xF) << 4) | (m.event & 0xF))
    assert len(body) == FLASH_BODY_LEN
    return body + _tag(key, body)


def decode_short(raw: bytes) -> Short:
    if len(raw) != FLASH_LEN:
        raise ValueError(f"flash and cancel messages are {FLASH_LEN} bytes, got {len(raw)}")
    b0, nid, ctr, se = struct.unpack_from("<BHHB", raw)
    return Short(node_id=nid, counter=ctr, severity=se >> 4, event=se & 0xF, msg_type=b0 & 0xF, version=b0 >> 4)


def short_tag_ok(raw: bytes, key: bytes) -> bool:
    return len(raw) == FLASH_LEN and hmac.compare_digest(raw[FLASH_BODY_LEN:], _tag(key, raw[:FLASH_BODY_LEN]))


def reconstruct(c16: int, last: int) -> int:
    """Smallest 32-bit counter above ``last`` whose low 16 bits are ``c16``, if it lies within the window; otherwise the nearest value at or below ``last`` (a stale or replayed counter)."""
    base = (last & ~0xFFFF) | c16
    for cand in (base - 65536, base, base + 65536):
        if last < cand <= last + WINDOW:
            return cand
    return base if base <= last else base - 65536


class SctBase:
    """Base-station rules for the two-stage design. Keeps, per short node id: the last accepted flash counter, the last accepted full-alert counter, and the last ``RECENT_N`` accepted
    (stage, counter) entries with their ACK (for the idempotent re-ACK). A full alert is accepted with or without a flash. Cancelled events are remembered, not deleted."""

    def __init__(self, key: bytes, recent_n: int = RECENT_N, pending_cancel: bool = False):
        # pending_cancel (V5 B1, default off = the tagged behaviour): a valid CANCEL for a counter above every counter accepted so far is remembered (at most recent_n of them) and applies when that alert arrives
        self.key, self.recent_n, self.pending_cancel = key, recent_n, pending_cancel
        self.pending: OrderedDict[tuple[int, int], None] = OrderedDict()
        self.last_flash: dict[int, int] = {}
        self.last_alert: dict[int, int] = {}
        self.recent: OrderedDict[tuple[int, str, int], bytes] = OrderedDict()
        self.cancelled: set[tuple[int, int]] = set()
        self.base_counter = 0

    def _remember(self, nid: int, stage: str, ctr: int, ack: bytes) -> None:
        self.recent[(nid, stage, ctr)] = ack
        while len(self.recent) > self.recent_n:
            self.recent.popitem(last=False)

    def _ack(self, node_id: int, event_id: int, ctr: int) -> bytes:
        self.base_counter += 1
        return P.encode_ack(P.Ack(node_id, event_id, ctr, self.base_counter), self.key)

    def handle_short(self, raw: bytes) -> tuple[str, bytes | None]:
        if len(raw) != FLASH_LEN:
            return REJECT_LENGTH, None
        if raw[0] >> 4 != P.VERSION:
            return REJECT_VERSION, None
        if raw[0] & 0xF not in (MSG_FLASH, MSG_CANCEL):
            return REJECT_TYPE, None
        if not short_tag_ok(raw, self.key):
            return REJECT_TAG, None
        m = decode_short(raw)
        nid = m.node_id
        if m.msg_type == MSG_CANCEL:
            c = reconstruct(m.counter, max(self.last_flash.get(nid, -1), self.last_alert.get(nid, -1)))
            if (nid, "flash", c) in self.recent or (nid, "alert", c) in self.recent:
                self.cancelled.add((nid, c))
                return CANCELLED, None
            if self.pending_cancel and c > max(self.last_flash.get(nid, -1), self.last_alert.get(nid, -1)):
                self.pending[(nid, c)] = None
                while len(self.pending) > self.recent_n:
                    self.pending.popitem(last=False)
                self.cancelled.add((nid, c))
                return CANCELLED, None
            return REJECT_UNKNOWN, None
        c = reconstruct(m.counter, self.last_flash.get(nid, -1))
        key = (nid, "flash", c)
        if key in self.recent:
            return REACK, self.recent[key]
        if c <= self.last_flash.get(nid, -1):
            return REJECT_COUNTER, None
        self.last_flash[nid] = c
        ack = self._ack(nid, FLASH_EVENT_ID, c)
        self._remember(nid, "flash", c, ack)
        return ACCEPT_FLASH, ack

    def handle_alert(self, raw: bytes) -> tuple[str, bytes | None]:
        if len(raw) != P.ALERT_LEN:
            return REJECT_LENGTH, None
        if raw[0] != P.VERSION:
            return REJECT_VERSION, None
        if raw[1] != P.MSG_ALERT:
            return REJECT_TYPE, None
        if not P.tag_ok(raw, self.key, P.ALERT_BODY_LEN):
            return REJECT_TAG, None
        a = P.decode_alert(raw)
        nid = a.node_id & 0xFFFF
        key = (nid, "alert", a.counter)
        if key in self.recent:
            return REACK, self.recent[key]
        if a.counter <= self.last_alert.get(nid, -1):
            return REJECT_COUNTER, None
        self.last_alert[nid] = a.counter
        ack = self._ack(a.node_id, a.event_id, a.counter)
        self._remember(nid, "alert", a.counter, ack)
        return ACCEPT_ALERT, ack


def airtimes(sfs=(7, 9, 12)) -> list[dict]:
    rows = []
    for name, n in (("flash / CANCEL", FLASH_LEN), ("alert", P.ALERT_LEN), ("ACK", P.ACK_LEN), ("heartbeat (assumed payload)", 16)):
        rows.append(dict(packet=name, bytes=n, **{f"sf{sf}_ms": airtime_ms(n, sf) for sf in sfs}))
    return rows


DOC = Path("docs/01_protocol/PROTOCOL_SCT.md")


def write_doc(path: Path = DOC) -> None:
    at = airtimes()
    t = "| Packet | Bytes | SF7 airtime (ms) | SF9 (ms) | SF12 (ms) |\n|---|---|---|---|---|\n" + "\n".join(f"| {r['packet']} | {r['bytes']} | {r['sf7_ms']:.1f} | {r['sf9_ms']:.1f} | {r['sf12_ms']:.1f} |" for r in at)
    ratio = {sf: airtime_ms(P.ALERT_LEN, sf) / airtime_ms(FLASH_LEN, sf) for sf in (7, 9, 12)}
    text = f"""# Severity-Classified Transmission (SCT): protocol (generated by `python -m crashguard.sct_protocol`; written before the S11 runs)

**Status.** Built in software only; every transmission result is SIMULATED, every MCU timing is an ASSUMPTION, nothing is measured on radios. The 10% duty cycle is a parameter and is NOT verified for India (WPC/DoT not checked). The severity table and the N16 scheduler remain the baselines; SCT is judged against the severity table and a null result is a valid outcome.

## 1. Two paths
- **Normal path:** Low and Moderate alerts, and heartbeats.
- **Fast path:** Severe and Critical alerts.

## 2. Severity-dependent hold (parameters)
| Class | Hold after the decision before the initial send |
|---|---|
| Critical | 0 s: send at once. If the driver cancels afterwards the car sends an authenticated CANCEL message (section 6) |
| Severe | `h_s` seconds (a short hold, tuned on tuning scenarios, grid 0, 1, 2, 3 s) |
| Moderate, Low | the full cancel window of the baselines (8 s and 10 s; Severe's full window is 6 s and Critical's is 5 s) |

## 3. Fast-path rules
1. **Preemption.** While a fast-path alert is active at a car (ready and not yet acknowledged or given up), that car holds back its normal-path alerts, retries and heartbeats; a normal transmission already on the air is not interrupted.
2. **No back-off before the initial send.** No random delay and no carrier sensing before the initial transmission (the baselines do not add one either).
3. **Two-stage send.** The car sends a 14-byte authenticated **flash** (device id, counter, severity class, event type, 8-byte truncated HMAC tag over all fields), listens for the ACK window, then sends the full 97-byte alert. The flash is repeated in each retry round until a signed ACK for it arrives; the alert until the signed ACK for the alert arrives. The base's idempotent re-ACK rule (one ACK per message per retry interval, every ACK paid from the base's duty-cycle budget) applies to both stages.
4. **Retry spacing until a signed ACK arrives:** 5 s for Critical and 10 s for Severe, with the same maximum numbers of tries as the severity table (12 and 8). Fixed spacing, no exponential growth.
5. **Spreading factor raised one step after the second failed try** (parameter, ablated; at most SF12). ASSUMPTION carried from N16: the base receives every spreading factor and the loss per transmission falls by a factor 0.7 per step.

## 4. Normal-path rules
Standard 97-byte alert, at most 3 tries with exponential back-off (4 s, doubling) and jitter (up to 50%), heartbeats are unconfirmed 16-byte packets that are batched (a heartbeat that could not be sent is merged into the next one, so one packet carries the latest state) and dropped under load (no fast-path pending, or tokens below the reserve). The simulator implements "dropped under load" and counts the share dropped; batching is part of the protocol text and is NOT modelled separately.

## 5. Duty-cycle budget
The duty-cycle limit is never exceeded (a token bucket in seconds of airtime, refilled at the duty rate, capacity 360 s). A reserved share `rho_f` (0.2, 0.35 or 0.5) of the bucket capacity can be spent by the fast path only; the normal path may use at most `1 - rho_f` of it (it may spend only while the tokens left after the send are at least `rho_f` times the capacity).

## 6. Byte layouts (little-endian; version 1; HMAC-SHA256 truncated to 8 bytes, same shared key as alert and ACK)
**Flash and CANCEL (14 bytes)**
| Offset | Size | Field |
|---|---|---|
| 0 | 1 | version (high nibble) and message type (low nibble): FLASH = 4, CANCEL = 5 |
| 1 | 2 | short node id: low 16 bits of `node_id` (ASSUMPTION: unique in the fleet) |
| 3 | 2 | counter: low 16 bits of the 32-bit alert counter of the event (the flash and the full alert of one event carry the same 32-bit counter) |
| 5 | 1 | severity class (high nibble, 0 to 3) and event type (low nibble: 0 crash, 1 rollover, 2 other; for CANCEL the reason, 0 = driver cancel) |
| 6 | 8 | tag = HMAC-SHA256(key, bytes 0 to 5), leading 8 bytes. **The tag covers every field of the body** |

**Full alert (97 bytes)** and **ACK (26 bytes):** unchanged (`docs/01_protocol/PACKET_FORMAT.md`). The ACK of a flash is the normal 26-byte ACK with `acked_event_id = 0xFFFFFFFF` and `acked_counter` = the reconstructed 32-bit counter; the node accepts it only for the flash it is waiting for.

**CANCEL.** Sent after the driver cancels an alert that was already transmitted (Critical, or Severe after `h_s`). It names the counter of the cancelled event. Unconfirmed, sent three times 2 s apart. The base marks the event cancelled (remembered, not deleted) only if the counter belongs to an accepted flash or alert; a CANCEL for an unknown counter is rejected; a repeated CANCEL changes nothing.

## 7. Base-station rules (reference code: `src/crashguard/sct_protocol.py`)
- A **full alert without a valid flash is accepted** (the flash is optional; the alert rules are those of `verifier.py`: valid tag and counter above the last accepted alert counter of that node, or an exact repeat of one of the last 16 accepted alerts, which gets the identical ACK again).
- A **flash** is accepted if its tag is valid and its counter, reconstructed from 16 bits within a window of +-32,768 of the last accepted flash counter, is above that counter; an exact repeat of a remembered flash gets the identical ACK again; a stale counter is rejected.
- The two counters are kept separately (last flash, last alert): a flash does not advance the alert counter, so the full alert with the same counter is accepted afterwards.
- Counters are never accepted twice; a forged or tampered flash, CANCEL or alert is rejected on the tag before any state changes.

## 8. Airtime (Semtech SX127x formula, `lora.airtime_ms`: 125 kHz, coding rate 4/5, 8-symbol preamble, explicit header, CRC on, low data-rate optimisation when the symbol is longer than 16 ms)
{t}

A flash takes {1 / ratio[7] * 100:.0f}% of the alert's airtime at SF7, {1 / ratio[9] * 100:.0f}% at SF9 and {1 / ratio[12] * 100:.0f}% at SF12 (alert airtime divided by flash airtime: {ratio[7]:.2f}, {ratio[9]:.2f}, {ratio[12]:.2f}). A round that sends flash then alert costs the sum of both.

## 9. What is NOT claimed
The 14-byte layout, the 16-bit counter window and the short node id are our design proposals; the firmware does not implement them; no MCU timing was measured (any timing in the simulator is an ASSUMPTION). Authentication is the same shared key as before: a holder of the key can forge any message. CANCEL is not acknowledged.
"""
    path.write_text(text, encoding="utf-8")


if __name__ == "__main__":
    write_doc()
    print(f"wrote {DOC}")
